/** 🌟 輔助函式：安全取得工作表並提供報錯，防範 Null 崩潰 */
function safeGetSheet(name) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(name);
  if (!sheet) {
    console.error("❌ 找不到關鍵工作表: " + name);
    return null;
  }
  return sheet;
}

function setupDatabase() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();
  const dbSchema = [
    {
      name: DB_TABLES.SETTINGS, headers: [['項目', '設定值', '說明']], color: '#f4cccc',
      initialData: [
        ['LINE_TOKEN', '', '貼上後點選安全隱藏'], ['AI_API_KEY', '', 'Gemini 2.5 Key'],
        ['GROQ_API_KEY', '', 'Groq API Key'], ['DRIVE_FOLDER_ID', '', 'Drive 存圖夾 ID'],
        ['MY_USER_ID', '', '您的 LINE ID'], ['BOT_NAME', 'Brian 秘書', '助理名稱'],
        ['USER_NAME', 'Brian 老師', '您的稱呼'], ['CALENDAR_ID_FAMILY', '', '家庭行事曆 ID'],
        ['CALENDAR_ID_ACTIVITY', '', '活動行事曆 ID'],
        ['CALENDAR_ID_SEMINAR', '', '研習行事曆 ID'],
        ['CALENDAR_ID_FINANCE', '', '金融理財行事曆 ID']
      ]
    },
    { name: DB_TABLES.TASKS, headers: [['日期', '任務內容', '詳細說明', '執行狀態', 'TaskID', 'txId']], color: '#fff2cc' },
    {
      name: DB_TABLES.KNOWLEDGE, headers: [['日期', '資源標題', '網址(URL)', '分類', '標籤', '重點摘要', '狀態(0未1已)', '縮圖URL', 'txId']], color: '#cfe2f3',
      initialData: [[new Date(), '範例：AI 學習筆記', 'https://ai.google', 'AI', '#技術, #學習', '這是一個範例摘要', 0, '', 'init_tx']]
    },
    { name: DB_TABLES.EXPENSE, headers: [['支付名稱', '類型', '原始額度', '已用金額', '剩餘額度', '結帳日', '備註']], color: '#ead1dc' },
    { name: DB_TABLES.KEYWORDS, headers: [['意圖類別', '定義']], color: '#d9ead3', initialData: [['EXPENSE_REWARD', '財務'], ['TASK', '任務']] },
    {
      name: DB_TABLES.LOCATIONS, headers: [['日期', '景點/餐廳名稱', '地址或區域', 'Google地圖連結', '相關情報(網址/重點)', '狀態(0未去1已去)', 'txId']], color: '#d0e0e3',
      initialData: [[new Date(), '範例：米其林餐廳', '台北市信義區', '', '記得提前訂位', 0, 'init_tx']]
    }
  ];

  dbSchema.forEach(schema => {
    let sheet = ss.getSheetByName(schema.name);
    if (!sheet) {
      sheet = ss.insertSheet(schema.name);
      sheet.getRange(1, 1, 1, schema.headers[0].length).setValues(schema.headers).setBackground(schema.color).setFontWeight('bold').setHorizontalAlignment('center');
      sheet.setFrozenRows(1);
      if (schema.initialData) sheet.getRange(2, 1, schema.initialData.length, schema.initialData[0].length).setValues(schema.initialData);
      sheet.autoResizeColumns(1, schema.headers[0].length);
    } else {
      const existingHeaders = sheet.getRange(1, 1, 1, Math.max(sheet.getLastColumn(), 1)).getValues()[0];
      const req = schema.headers[0];
      let missing = [];
      req.forEach(h => { if (!existingHeaders.includes(h)) missing.push(h); });
      if (missing.length > 0) {
        sheet.getRange(1, existingHeaders.length + 1, 1, missing.length).setValues([missing]).setBackground(schema.color).setFontWeight('bold').setHorizontalAlignment('center');
      }
     
      // V3.9.1 深層資料自癒邏輯 (自動補齊缺失設定欄位)
      if (schema.initialData) {
        const existingData = sheet.getDataRange().getValues();
        const existingKeys = existingData.map(r => String(r[0]).trim());
        let currentHeaderLen = existingHeaders.length + missing.length;
       
        schema.initialData.forEach(initRow => {
          if (!existingKeys.includes(String(initRow[0]).trim())) {
            let newRow = new Array(currentHeaderLen).fill("");
            for (let i = 0; i < initRow.length; i++) newRow[i] = initRow[i];
            sheet.appendRow(newRow);
          }
        });
      }
    }
  });

  if (!ScriptApp.getProjectTriggers().some(t => t.getHandlerFunction() === 'autoSyncTasks')) ScriptApp.newTrigger('autoSyncTasks').timeBased().everyMinutes(30).create();
  if (!ScriptApp.getProjectTriggers().some(t => t.getHandlerFunction() === 'checkAndResetExpenses_')) ScriptApp.newTrigger('checkAndResetExpenses_').timeBased().atHour(5).everyDays(1).create();
 
  SpreadsheetApp.getUi().alert('✅ 系統巡邏與修復完成！\n缺失的欄位或設定項目已為您自動補齊。');
}

function hideAndSaveSecrets() {
  const sheet = safeGetSheet(DB_TABLES.SETTINGS);
  if (!sheet) return;
  const props = PropertiesService.getScriptProperties();
  const data = sheet.getDataRange().getValues();
 
  for (let i = 1; i < data.length; i++) {
    const key = data[i][0] ? String(data[i][0]).trim() : "";
    const val = data[i][1] ? String(data[i][1]).trim() : "";
    if (key && val && !val.includes('***')) {
      props.setProperty(key, val);
      sheet.getRange(i + 1, 2).setValue('**** (已加密隱藏)');
    }
  }
  SpreadsheetApp.getUi().alert('🔒 企業級安全核心加密完成');
}

