function manualSyncTasks() { autoSyncTasks(); checkAndResetExpenses_(); SpreadsheetApp.getActiveSpreadsheet().toast('🔄 巡邏完畢'); }
function autoSyncTasks() { resetDailyUsage_(); syncTasksLogic(); }

function resetDailyUsage_() {
  const props = PropertiesService.getScriptProperties(), todayStr = Utilities.formatDate(new Date(), "GMT+8", "yyyy-MM-dd");
  if (props.getProperty('LAST_RESET_DATE') !== todayStr) {
    props.setProperty('LAST_RESET_DATE', todayStr); props.setProperty('GEMINI_USAGE', '0'); props.setProperty('GROQ_TOKEN_USAGE', '0');
  }
}

function syncTasksLogic() {
  const sheet = safeGetSheet(DB_TABLES.TASKS);
  if (!sheet) return;
  const data = sheet.getDataRange().getValues();
  if (data.length < 2) return;
  const statusIdx = data[0].indexOf('執行狀態'), taskIdIdx = data[0].indexOf('TaskID');
  if (statusIdx === -1 || taskIdIdx === -1) return;
  for (let i = 1; i < data.length; i++) {
    if (data[i][statusIdx] === '未完成' && data[i][taskIdIdx]) {
      try { if (Tasks.Tasks.get('@default', data[i][taskIdIdx]).status === 'completed') sheet.getRange(i + 1, statusIdx + 1).setValue('✅ 已完成'); } catch(e){}
    }
  }
}

function checkAndResetExpenses_() {
  const sheet = safeGetSheet(DB_TABLES.EXPENSE);
  if (!sheet) return;
  const data = sheet.getDataRange().getValues();
  if (data.length < 2) return;
  const props = PropertiesService.getScriptProperties();
  const payCol = data[0].indexOf('支付名稱'), billDayCol = data[0].indexOf('結帳日'), usedCol = data[0].indexOf('已用金額'), origCol = data[0].indexOf('原始額度'), remainCol = data[0].indexOf('剩餘額度');
  if (payCol === -1 || billDayCol === -1) return;
  const [yyyy, mm, dd] = Utilities.formatDate(new Date(), "GMT+8", "yyyy-MM-dd").split('-').map(Number);
  for (let i = 1; i < data.length; i++) {
    const payName = data[i][payCol], billDayRaw = data[i][billDayCol];
    if (!payName || !billDayRaw) continue;
    const billDay = parseInt(billDayRaw);
    let cycleYear = yyyy, cycleMonth = mm;
    let maxDays = new Date(cycleYear, cycleMonth, 0).getDate();
    if (dd < Math.min(billDay, maxDays)) { cycleMonth -= 1; if (cycleMonth === 0) { cycleMonth = 12; cycleYear -= 1; } }
    const cycleStartStr = `${cycleYear}-${String(cycleMonth).padStart(2, '0')}-${String(Math.min(billDay, new Date(cycleYear, cycleMonth, 0).getDate())).padStart(2, '0')}`;
    if (props.getProperty('RESET_' + payName) !== cycleStartStr) {
      if (usedCol !== -1) sheet.getRange(i + 1, usedCol + 1).setValue(0);
      if (remainCol !== -1 && origCol !== -1) sheet.getRange(i + 1, remainCol + 1).setValue(data[i][origCol]);
      props.setProperty('RESET_' + payName, cycleStartStr);
    }
  }
}

