function generateTxId_() { return 'tx_' + new Date().getTime() + '_' + Math.floor(Math.random() * 10000); }

function fetchWithRetry_(url, options, maxRetries = 2) {
  options.muteHttpExceptions = true;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      const res = UrlFetchApp.fetch(url, options);
      if (res.getResponseCode() === 200) return res;
      if (i === maxRetries) throw new Error(`Status ${res.getResponseCode()}`);
      Utilities.sleep(1000);
    } catch (e) { if (i === maxRetries) throw e; Utilities.sleep(1000); }
  }
}

function dynamicAppendRow_(sheetName, rowDataObj) {
  const sheet = safeGetSheet(sheetName);
  if (!sheet) return;
  const headers = sheet.getRange(1, 1, 1, Math.max(sheet.getLastColumn(), 1)).getValues()[0];
  let rowArray = new Array(headers.length).fill("");
  for (const key in rowDataObj) { const idx = headers.indexOf(key); if (idx !== -1) rowArray[idx] = rowDataObj[key]; }
  sheet.appendRow(rowArray);
}

function doPost(e) {
  const lock = LockService.getScriptLock();
  try { lock.waitLock(10000); } catch (err) { return; }
  let replyToken = "", userMsg = "";
  try {
    const props = PropertiesService.getScriptProperties();
    const config = {
      API_KEY_A: props.getProperty('AI_API_KEY'), GROQ_API_KEY: props.getProperty('GROQ_API_KEY'),
      TOKEN: props.getProperty('LINE_TOKEN'), BOT_NAME: props.getProperty('BOT_NAME') || 'Brian 秘書',
      USER_NAME: props.getProperty('USER_NAME') || '老師', FOLDER_ID: props.getProperty('DRIVE_FOLDER_ID')
    };
    const parsedData = JSON.parse(e.postData.contents);
    if (!parsedData.events || parsedData.events.length === 0) return;
    const event = parsedData.events[0];
    replyToken = event.replyToken || "";
    if (event.type !== 'message' || !event.message) return;
    
    if (event.message.type === 'image') { handleImageMessage_(event, config, props, replyToken); return; }
    userMsg = event.message.text || "";
    if (userMsg.trim() === "") return;
    if (userMsg.length > 2000) userMsg = userMsg.substring(0, 2000) + "\n\n[系統截斷保護]";
    
    const correctionMatch = userMsg.match(/(不對|錯了|改到|改成|改為|這是|存到)(記帳|待辦|任務|資源|倉庫|日曆|旅遊|tasks|task|keep|calendar|map)/i);
    if (correctionMatch) { handleCorrection_(replyToken, correctionMatch[2].toLowerCase(), config); return; }
    
    // 紀錄執行前的 Token 用量，計算單次耗損
    const initGroq = parseInt(props.getProperty('GROQ_TOKEN_USAGE') || '0');
    const initGem = parseInt(props.getProperty('GEMINI_USAGE') || '0');
    
    const execResult = runLightningCore_(userMsg, config, props);
    let report = ""; let actionsToCache = []; const txId = generateTxId_();
    
    execResult.data.forEach((item, index) => {
      const actionData = executeAction_(item, userMsg, props, txId);
      report += `${index + 1}. ${actionData.res}\n`;
      actionsToCache.push(actionData.cache);
    });
    saveLastAction_(actionsToCache);
    
    // 計算單次用量並顯示
    const finalGroq = parseInt(props.getProperty('GROQ_TOKEN_USAGE') || '0');
    const finalGem = parseInt(props.getProperty('GEMINI_USAGE') || '0');
    const diffGroq = finalGroq - initGroq;
    const diffGem = finalGem - initGem;
    
    let footer = "";
    if (diffGroq > 0) {
      footer = `⚡ B: 本次 ${(diffGroq/1000).toFixed(1)}k | 剩餘 ${(100 - finalGroq/1000).toFixed(1)}k\n🛡️ A: 剩餘 ${20 - finalGem}/20 次\n[${execResult.source}]`;
    } else {
      footer = `🛡️ A: 本次 ${diffGem} 次 | 剩餘 ${20 - finalGem}/20 次\n⚡ B: 剩餘 ${(100 - finalGroq/1000).toFixed(1)}k\n[${execResult.source}]`;
    }
    
    if (replyToken) replyToLine_(replyToken, `🛰️ ${config.BOT_NAME} 報告：\n\n${report.trim()}\n\n${footer}`, config.TOKEN);
  } catch (err) {
    console.error("Critical Webhook Error: " + err.message);
    const errorMsg = `⚠️ 報告，運算發生異常：${err.message.substring(0, 40)}`;
    if (replyToken) { try { replyToLine_(replyToken, errorMsg, PropertiesService.getScriptProperties().getProperty('LINE_TOKEN')); } catch(e){} }
  } finally { lock.releaseLock(); }
}

function runLightningCore_(msg, config, props) {
  const groqModels = [{ name: "llama-3.3-70b-versatile", label: "⚡ 閃電 B1 (70B)" }, { name: "llama-3.1-8b-instant", label: "🔄 降級備援 B2 (8B)" }];
  for (let i = 0; i < groqModels.length; i++) {
    try { const result = callGroqAPI_(msg, groqModels[i].name, config, props); if (result) return { data: result, source: groqModels[i].label }; } catch (e) { if (e.message.includes('401')) break; }
  }
  try { return { data: callGeminiNative_(msg, config, props), source: "🛡️ 原生兜底 A (2.5)" }; } catch (e) { throw new Error("大腦通訊崩潰"); }
}

function getDynamicPayTools_() {
  const sheet = safeGetSheet(DB_TABLES.EXPENSE);
  if (!sheet) return "";
  const data = sheet.getDataRange().getValues(), payCol = data[0].indexOf('支付名稱');
  if (payCol === -1) return "";
  let tools = [];
  for (let i = 1; i < data.length; i++) { if (data[i][payCol]) tools.push(data[i][payCol].toString().trim()); }
  return tools.join(", ");
}

